package com.erudit.notificator;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.erudit.notificator.model.*;import com.erudit.notificator.repository.DeliveryRepository;import com.erudit.notificator.service.MockNotificationSender;import java.lang.reflect.Field;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class MockNotificationSenderTest {@Test void appliesQuietHoursAndDailyLimitWithoutNetwork()throws Exception{var repository=mock(DeliveryRepository.class);var sender=new MockNotificationSender(repository);set(sender,"dailyLimit",1);set(sender,"quietStart",22);set(sender,"quietEnd",8);var n=new NotificationRecord(UUID.randomUUID(),UUID.randomUUID(),"DEMO","Title","Body",false,OffsetDateTime.now());when(repository.record(eq(n),any())).thenAnswer(i->new DeliveryAttempt(UUID.randomUUID(),n.id(),1,i.getArgument(1),"preview",OffsetDateTime.now()));
 assertThat(sender.send(n,OffsetDateTime.parse("2026-01-01T23:00:00Z")).status()).isEqualTo("SKIPPED_QUIET_HOURS");when(repository.deliveredToday(n.userId())).thenReturn(1L);assertThat(sender.send(n,OffsetDateTime.parse("2026-01-01T12:00:00Z")).status()).isEqualTo("SKIPPED_DAILY_LIMIT");when(repository.deliveredToday(n.userId())).thenReturn(0L);assertThat(sender.send(n,OffsetDateTime.parse("2026-01-01T12:00:00Z")).status()).isEqualTo("MOCK_DELIVERED");}
 private static void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}}
